 let resizeChange=$state<{item:ScheduleItem;end:string}|null>(null);
 function resizeFrom(item:ScheduleItem,start:string,end:string,allDay:boolean){if(resizeChange)return;if(item.allDay!==allDay||(allDay?start!==item.start:DateTime.fromISO(start).toMillis()!==DateTime.fromISO(item.start).toMillis())){notice=text.invalid;return;}returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;resizeChange={item,end};}
 let compactMode=$state(false),desktopExpanded=$state(true),mobileExpanded=$state(false);
