  desktopExpanded=true;mobileExpanded=false;if(!user)return;
  try{const saved=JSON.parse(localStorage.getItem(`schedule-calendar-panel:v1:${user.id}`)??'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved)){if(typeof saved.desktopExpanded==='boolean')desktopExpanded=saved.desktopExpanded;if(typeof saved.mobileExpanded==='boolean')mobileExpanded=saved.mobileExpanded;}}catch{/* The panel remains usable without browser storage. */}
 }
