 }
 let dateOpen=$state(false);
 let settingsOpen=$state(false),settingsDiscard=$state(false),settingsError=$state(''),settingsTrigger=$state<HTMLButtonElement|null>(null);
 let displayDraft=$state<Pick<ScheduleSettings,'firstDay'|'mode'> & {timeAxis:'vertical'|'horizontal'}>({firstDay:1,mode:'overlay',timeAxis:'vertical'});
 let settingsLabel=$derived(`${text.title} · ${localeMessages[$localization.displayLanguage].navigation.settings}`);
 let displayDirty=$derived(displayDraft.firstDay!==settings.firstDay||displayDraft.mode!==settings.mode||displayDraft.timeAxis!==(settings.timeAxis??'vertical'));
 function openSettings(trigger:HTMLButtonElement){displayDraft={firstDay:settings.firstDay,mode:settings.mode,timeAxis:settings.timeAxis??'vertical'};settingsError='';settingsTrigger=trigger;settingsOpen=true;}
 function closeSettings(){if(prefSaving)return;if(displayDirty)settingsDiscard=true;else settingsOpen=false;}
 async function saveSettings(){if(prefSaving||!displayDirty)return;prefSaving=true;settingsError='';try{const result=await scheduleRequest<{revision:number;settings:ScheduleSettings}>('/v1/employees/me/schedule-preferences','PUT',{settings:{...$state.snapshot(settings),...$state.snapshot(displayDraft)},expectedRevision:revision});settings=result.data.settings;revision=result.data.revision;batch=0;settingsOpen=false;}catch{settingsError=text.preferencesFailed;}finally{prefSaving=false;}}
 let lastLoadKey='';let generation=0,controller:AbortController|undefined,detailGeneration=0,loadedQuery='';
 let visible=$derived(settings.calendars.filter(c=>c.visible)),sideCalendars=$derived(visible.slice(batch*5,batch*5+5));
 let range=$derived.by(()=>{let start=DateTime.fromISO(date,{zone:$localization.timeZone});if(settings.view==='week')start=start.minus({days:(start.weekday%7-settings.firstDay+7)%7});else if(settings.view==='month'){start=start.startOf('month');start=start.minus({days:(start.weekday%7-settings.firstDay+7)%7});}return {start:start.startOf('day').toISO()!,end:start.startOf('day').plus({days:settings.view==='day'?1:settings.view==='week'?7:42}).toISO()!};});
 let mobileDays=$derived.by(()=>{const start=DateTime.fromISO(range.start,{setZone:true});return Array.from({length:settings.view==='month'?42:settings.view==='week'?7:0},(_,n)=>start.plus({days:n}).toISODate()!);});
 let dailyItems=$derived(items.filter(i=>(mobileCalendar==='all'||i.calendarKeys?.includes(mobileCalendar))).filter(i=>i.allDay?i.start<=date&&i.end>date:DateTime.fromISO(i.start,{zone:$localization.timeZone}).toISODate()!<=date&&DateTime.fromISO(i.end,{zone:$localization.timeZone}).minus({milliseconds:1}).toISODate()!>=date));
 async function load(){if(!user||!canOperate(user,'schedule.read'))return;const current=++generation;controller?.abort();controller=new AbortController();loading=true;const calendars=visible.map(c=>c.key).join(',');if(!calendars){items=[];loading=false;return;}try{const query=`?start=${encodeURIComponent(range.start)}&end=${encodeURIComponent(range.end)}&calendars=${encodeURIComponent(calendars)}`;const [result,context]=await Promise.all([allSchedulePages<ScheduleItem>('/v1/schedule-occurrences'+query,controller.signal),scheduleRequest<{days:typeof contextDays}>('/v1/schedule-context'+query,'GET',undefined,{},controller.signal)]);if(current===generation){items=result;contextDays=context.data.days;error='';}}catch(e){if(current===generation&&!(e instanceof DOMException&&e.name==='AbortError')){items=[];error=text.failed;}}finally{if(current===generation)loading=false;}}
 async function preferenceChanged(){batch=0;if(!user)return;prefSaving=true;try{const result=await scheduleRequest<{revision:number;settings:ScheduleSettings}>('/v1/employees/me/schedule-preferences','PUT',{settings:$state.snapshot(settings),expectedRevision:revision});revision=result.data.revision;}catch{notice=text.preferencesFailed;}finally{prefSaving=false;}}
 function changeView(view:ScheduleSettings['view']){settings.view=view;void preferenceChanged();}
 function move(delta:number){date=DateTime.fromISO(date).plus(settings.view==='day'?{days:delta}:settings.view==='week'?{weeks:delta}:{months:delta}).toISODate()!;}
 async function open(item:Pick<ScheduleItem,'key'>,trigger:HTMLElement|null=null){const version=++detailGeneration;try{const result=await scheduleRequest<ScheduleItem>(`/v1/schedule-occurrences/${encodeURIComponent(item.key)}`);if(version!==detailGeneration)return;selected=result.data;returnFocus=trigger??(document.activeElement instanceof HTMLElement?document.activeElement:null);const day=result.data.allDay?result.data.start:DateTime.fromISO(result.data.start,{zone:$localization.timeZone}).toISODate()!;if(day<range.start.slice(0,10)||day>=range.end.slice(0,10))date=day;}catch{if(version===detailGeneration)notice=text.unavailable;}}
 function closeDetail(){
  ++detailGeneration;selected=null;loadedQuery='';
  if(page.url.searchParams.has('occurrence')){
   const url=new URL(page.url);url.searchParams.delete('occurrence');const state=page.state;
   replaceState(url,state);
   // Shallow routing updates the address immediately; navigation also synchronizes page.url.
   void goto(url,{replaceState:true,noScroll:true,keepFocus:true,state}).catch(()=>{/* The address remains clean if navigation fails. */});
  }
 }
 function newDraft(start?:string,end?:string,allDay=false){if(!user||!canOperate(user,'schedule.create'))return;returnFocus=document.activeElement as HTMLElement;editing=null;draftSource=null;selected=null;const local=(value:string)=>DateTime.fromISO(value,{zone:$localization.timeZone}).toFormat("yyyy-MM-dd'T'HH:mm");const now=DateTime.now().setZone($localization.timeZone).set({minute:0,second:0,millisecond:0});draft={title:'',description:'',location:'',visibility:'public',timeZone:$localization.timeZone,allDay,start:allDay?start!.slice(0,10):start?local(start):date+'T'+now.toFormat('HH:mm'),end:allDay?end!.slice(0,10):end?local(end):DateTime.fromISO(date+'T'+now.toFormat('HH:mm'),{zone:$localization.timeZone}).plus({hours:1}).toFormat("yyyy-MM-dd'T'HH:mm"),attendeeIds:[],resourceIds:[],recurrence:null};}
 function draftFrom(item:ScheduleItem,copy=false,start=item.start,end=item.end,allDay=item.allDay){if(!item.detailAvailable||!user)return;const local=(value:string)=>DateTime.fromISO(value,{zone:item.timeZone}).toFormat("yyyy-MM-dd'T'HH:mm");draft={title:item.title??'',description:item.description??'',location:item.location??'',visibility:item.visibility??'public',timeZone:item.timeZone,allDay,start:allDay?start.slice(0,10):local(start),end:allDay?end.slice(0,10):local(end),attendeeIds:item.participants?.map(p=>p.employeeId).filter(id=>id!==user!.id)??[],resourceIds:item.resources?.map(r=>r.id)??[],recurrence:null};editing=copy?null:item;draftSource=item;if(!allDay){draft.startOffset=DateTime.fromISO(start,{zone:item.timeZone}).offset;draft.endOffset=DateTime.fromISO(end,{zone:item.timeZone}).offset;}selected=null;}
 async function changed(key?:string){await load();if(key)await open({key});else if(selected)await open(selected);}
 function addCalendar(item:EmployeeChoice|RoomChoice){if(prefSaving)return;const key=`${'employeeCode' in item?'employee':'resource'}:${item.id}`;if(settings.calendars.some(c=>c.key===key))return;if(settings.calendars.length>=20){notice=text.limit;return;}const palette=['#2563eb','#0f766e','#9333ea','#c2410c','#be185d','#4d7c0f'];settings.calendars=[...settings.calendars,{key,name:'employeeCode' in item?item.name:item.room.name,color:palette[settings.calendars.length%palette.length],visible:true}];void preferenceChanged();}
 function reorder(index:number,delta:number){const next=[...settings.calendars];[next[index],next[index+delta]]=[next[index+delta],next[index]];settings.calendars=next;void preferenceChanged();}
 onMount(()=>{const media=matchMedia(COMPACT_CONTENT_QUERY);compactMode=media.matches;const mediaChanged=()=>compactMode=media.matches;media.addEventListener('change',mediaChanged);let disposed=false;void(async()=>{try{user=await readSessionUser();if(!user||!canOperate(user,'schedule.read')){loading=false;return;}restorePanel();date=DateTime.now().setZone($localization.timeZone).toISODate()!;const result=await scheduleRequest<{revision:number;settings:ScheduleSettings}>('/v1/employees/me/schedule-preferences');if(disposed)return;settings=result.data.settings;revision=result.data.revision;ready=true;}catch{error=text.failed;loading=false;}})();return()=>{disposed=true;media.removeEventListener('change',mediaChanged);++generation;++detailGeneration;controller?.abort();};});
 $effect(()=>{const key=JSON.stringify([range,visible.map(c=>c.key)]);if(!ready||key===lastLoadKey)return;lastLoadKey=key;untrack(()=>void load());});
