</script>
<AssetManagementShell title={text.title}>
 <div class="schedule-page"><h1 class="sr-only">{text.title}</h1>
  <div class="toolbar"><div class="date-nav"><ControlButton class="calendar-panel-toggle" type="button" aria-label={calendarList?text.hideCalendars:text.showCalendars} title={calendarList?text.hideCalendars:text.showCalendars} aria-expanded={calendarList} aria-controls="schedule-calendar-panel" disabled={!ready} onclick={togglePanel} data-button-scope="button-8faf3f69b7"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></ControlButton><ActionButton type="button" aria-label={text.previous} onclick={()=>move(-1)} variant="secondary" data-button-scope="button-8faf3f69b7">‹</ActionButton><ActionButton type="button" onclick={()=>date=DateTime.now().setZone($localization.timeZone).toISODate()!} variant="secondary" data-button-scope="button-8faf3f69b7">{text.today}</ActionButton><ActionButton type="button" aria-label={text.next} onclick={()=>move(1)} variant="secondary" data-button-scope="button-8faf3f69b7">›</ActionButton><div class="date-field"><DatePicker label={text.date} field="schedule-date" value={date} showLabel={false} required open={dateOpen} onToggle={()=>dateOpen=!dateOpen} onSelect={value=>{date=value;dateOpen=false;}}/></div></div><div class="views" aria-label={text.title}>{#each ['day','week','month'] as view}<ActionButton type="button" disabled={prefSaving} aria-pressed={settings.view===view} onclick={()=>changeView(view as ScheduleSettings['view'])} variant="secondary" data-button-scope="button-8faf3f69b7">{text[view as 'day']}</ActionButton>{/each}</div><div class="tools"><ControlButton type="button" class="schedule-settings" aria-label={settingsLabel} title={settingsLabel} aria-haspopup="dialog" aria-expanded={settingsOpen} aria-controls="schedule-display-settings" disabled={!ready||prefSaving||!canOperate(user,'schedule.preferences.update')} onclick={event=>openSettings(event.currentTarget)} data-button-scope="button-8faf3f69b7">{@html icons.settings}</ControlButton>{#if canOperate(user,'schedule.create')}<ModalActionButton class="app-primary-action" type="button" onclick={()=>newDraft()} variant="primary" data-button-scope="button-8faf3f69b7">{text.create}</ModalActionButton>{/if}</div></div>
  {#if notice}<StatusNotice message={notice} tone="error" onDismiss={()=>notice=''}/>{/if}
  {#if error}<StatusNotice message={error} tone="error" onDismiss={()=>error=''}/><ActionButton type="button" onclick={()=>load()} variant="secondary" data-button-scope="button-8faf3f69b7">{text.retry}</ActionButton>{/if}
  {#if user&&!canOperate(user,'schedule.read')}<p>{text.schedulePermission}</p>{:else}
  <div class="workspace" class:no-calendars={!ready||!calendarList}>
   {#if ready}<aside id="schedule-calendar-panel" class="calendar-list" aria-label={text.calendars} hidden={!compactMode&&!calendarList}><div class="list-heading"><h2>{#if compactMode}<ControlButton class="calendar-accordion" type="button" aria-expanded={calendarList} aria-controls="schedule-calendar-choices" onclick={togglePanel} data-button-scope="button-8faf3f69b7"><span>{text.calendars}</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true" class:expanded={calendarList}><path d="m6 9 6 6 6-6"/></svg></ControlButton>{:else}{text.calendars}{/if}</h2><AddButton label={text.addCalendar} disabled={prefSaving} onclick={()=>picker=true}/></div><div id="schedule-calendar-choices" hidden={!calendarList}><div class="calendar-choices">{#each settings.calendars as calendar,index(calendar.key)}<div class="calendar-choice"><div class="toggle"><FormCheckbox label={calendar.name} field={`schedule-visible-${calendar.key}`} checked={calendar.visible} disabled={prefSaving} onChange={value=>{calendar.visible=value;void preferenceChanged();}}/></div><div class="calendar-actions"><div class="color-field"><FormColorPicker label={`${calendar.name} · ${text.color}`} field={`schedule-color-${calendar.key}`} value={calendar.color} disabled={prefSaving} onSelect={value=>{calendar.color=value;void preferenceChanged();}}/></div><ActionButton type="button" aria-label={`${text.moveUp} ${calendar.name}`} disabled={prefSaving||index===0} onclick={()=>reorder(index,-1)} variant="secondary" data-button-scope="button-8faf3f69b7">↑</ActionButton><ActionButton type="button" aria-label={`${text.moveDown} ${calendar.name}`} disabled={prefSaving||index===settings.calendars.length-1} onclick={()=>reorder(index,1)} variant="secondary" data-button-scope="button-8faf3f69b7">↓</ActionButton><ActionButton type="button" disabled={prefSaving} aria-label={`${text.remove} ${calendar.name}`} onclick={()=>{settings.calendars=settings.calendars.filter(c=>c.key!==calendar.key);void preferenceChanged();}} variant="secondary" data-button-scope="button-8faf3f69b7">×</ActionButton></div></div>{/each}</div></div></aside>{/if}
   <section class="calendar-content" aria-label={text.title} aria-busy={loading}>
    {#if loading}<p role="status">{text.loading}</p>{:else if !error&&ready}
     <div class="desktop-board" class:horizontal-board={settings.timeAxis==='horizontal'&&settings.view!=='month'}>{#if settings.timeAxis==='horizontal'&&settings.view!=='month'||settings.mode==='overlay'}<ScheduleBoard timeAxis={settings.timeAxis??'vertical'} view={settings.view} {date} firstDay={settings.firstDay} {items} calendars={visible} context={settings.timeAxis==='horizontal'&&settings.view!=='month'?contextDays:contextDays.filter(d=>d.calendarKey===(visible.find(c=>c.key===`employee:${user?.id}`)?.key??visible[0]?.key))} editable={!resizeChange&&canOperate(user,'schedule.update')} creatable={canOperate(user,'schedule.create')} onOpen={item=>open(item)} onCreate={newDraft} onMove={(item,start,end,allDay)=>draftFrom(item,false,start,end,allDay)} onResize={resizeFrom}/>{:else}<div class="batch-nav"><span>{text.comparison}: {batch*5+1}–{Math.min(batch*5+5,visible.length)} / {visible.length}</span><ActionButton type="button" disabled={batch===0} onclick={()=>batch--} variant="secondary" data-button-scope="button-8faf3f69b7">{text.previous}</ActionButton><ActionButton type="button" disabled={(batch+1)*5>=visible.length} onclick={()=>batch++} variant="secondary" data-button-scope="button-8faf3f69b7">{text.next}</ActionButton></div><div class="side-boards" style={`--calendar-count:${Math.max(1,sideCalendars.length)}`}>{#each sideCalendars as calendar(calendar.key)}<div><h3 style={`border-color:${calendar.color}`}>{calendar.name}</h3><ScheduleBoard timeAxis={settings.timeAxis??'vertical'} view={settings.view} {date} firstDay={settings.firstDay} items={items.filter(i=>i.calendarKeys?.includes(calendar.key))} calendars={[calendar]} context={contextDays.filter(d=>d.calendarKey===calendar.key)} editable={!resizeChange&&canOperate(user,'schedule.update')} creatable={canOperate(user,'schedule.create')} onOpen={item=>open(item)} onCreate={newDraft} onMove={(item,start,end,allDay)=>draftFrom(item,false,start,end,allDay)} onResize={resizeFrom}/></div>{/each}</div>{/if}</div>
     <div class="mobile-agenda" class:horizontal-board={settings.timeAxis==='horizontal'&&settings.view!=='month'}><div class="mobile-calendar-select"><SearchSelect label={text.calendars} field="schedule-mobile-calendar" value={mobileCalendar} options={[{value:"all",label:text.allNotifications},...visible.map(c=>({value:c.key,label:c.name}))]} onSelect={value=>mobileCalendar=value}/></div>{#if mobileDays.length}<div class="mobile-days" class:month-days={settings.view==='month'} aria-label={settings.view==='month'?text.month:text.week}>{#each mobileDays as day}<ActionButton type="button" aria-pressed={day===date} aria-label={day} onclick={()=>date=day} class={['',(day===date?"chosen":'')]} variant="secondary" data-button-scope="button-8faf3f69b7"><small>{DateTime.fromISO(day).setLocale($localization.displayLanguage).toFormat('ccc')}</small><span>{Number(day.slice(-2))}</span></ActionButton>{/each}</div>{/if}<h2>{new Intl.DateTimeFormat($localization.displayLanguage,{dateStyle:'full',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))}</h2>{#each contextDays.filter(d=>d.date===date&&(mobileCalendar==='all'?d.calendarKey===visible[0]?.key:d.calendarKey===mobileCalendar)) as context}<p class="context-day">{context.title}</p>{/each}{#each dailyItems as item(item.key)}<ControlButton type="button" class="agenda-event" onclick={event=>open(item,event.currentTarget)} data-button-scope="button-8faf3f69b7"><span class="time">{item.allDay?text.allDay:DateTime.fromISO(item.start,{zone:$localization.timeZone}).toFormat('HH:mm')}</span><span>{item.title??text.busy}<small>{item.calendarKeys?.map(key=>settings.calendars.find(c=>c.key===key)?.name).join(' · ')}</small></span></ControlButton>{:else}<p>{text.empty}</p>{/each}</div>
    {/if}
   </section>
  </div>{/if}
 </div>
</AssetManagementShell>
{#snippet employeeCalendars()}<ScheduleDirectory kind="employees" selected={settings.calendars.filter(c=>c.key.startsWith('employee:')).map(c=>Number(c.key.split(':')[1]))} onSelect={addCalendar}/>{/snippet}
{#snippet roomCalendars()}<ScheduleDirectory kind="rooms" selected={settings.calendars.filter(c=>c.key.startsWith('resource:')).map(c=>Number(c.key.split(':')[1]))} onSelect={addCalendar}/>{/snippet}
{#if picker}<DetailModal title={text.addCalendar} titleId="schedule-calendar-picker" closeLabel={text.close} onClose={()=>picker=false}><DetailTabs bind:active={pickerKind} label={text.addCalendar} tabs={[{id:'employees',label:text.employees,content:employeeCalendars},{id:'rooms',label:text.rooms,content:roomCalendars}]}/></DetailModal>{/if}
{#if selected&&user}<ScheduleDetail item={selected} {user} {returnFocus} onClose={closeDetail} onEdit={()=>draftFrom(selected!)} onCopy={()=>draftFrom(selected!,true)} onChanged={()=>changed()}/>{/if}
{#if draft&&user}<ScheduleEditor {user} item={editing} source={draftSource} initial={draft} {returnFocus} onClose={()=>{draft=null;editing=null;}} onSaved={key=>changed(key)}/>{/if}
{#if resizeChange}<ScheduleResize item={resizeChange.item} end={resizeChange.end} {returnFocus} onClose={()=>resizeChange=null} onError={message=>{notice=message;void load();}} onSaved={async()=>{resizeChange=null;await load();}}/>{/if}
{#if settingsOpen}<DetailModal title={settingsLabel} titleId="schedule-display-settings" closeLabel={text.close} returnFocus={settingsTrigger} initialFocusSelector="[aria-controls=schedule-first-day-options]" onClose={closeSettings}>
 {#if settingsError}<StatusNotice message={settingsError} tone="error" onDismiss={()=>settingsError=''}/>{/if}
 <div class="schedule-settings-sections"><FormSection title={text.basicSettings} framed columns={2}>
  <SearchSelect label={text.firstDay} searchable={false} field="schedule-first-day" value={String(displayDraft.firstDay)} options={[{value:'1',label:text.monday},{value:'0',label:text.sunday}]} disabled={prefSaving} onSelect={value=>displayDraft.firstDay=Number(value) as 0|1}/>
  <SearchSelect label={text.calendars} searchable={false} field="schedule-mode" value={displayDraft.mode} options={[{value:'overlay',label:text.overlay},{value:'side',label:text.side}]} disabled={prefSaving} onSelect={value=>displayDraft.mode=value as typeof displayDraft.mode}/>
 </FormSection>
 <FormSection title={text.displaySettings} framed columns={2}>
  <SearchSelect label={text.timeAxis} searchable={false} field="schedule-time-axis" value={displayDraft.timeAxis} options={[{value:'vertical',label:text.vertical},{value:'horizontal',label:text.horizontal}]} disabled={prefSaving} onSelect={value=>displayDraft.timeAxis=value as typeof displayDraft.timeAxis}/>
  <p class="axis-hint">{text.timeAxisHint}</p>
 </FormSection></div>
 {#snippet actions()}<ModalActionButton label={text.cancel} variant="secondary" disabled={prefSaving} onclick={closeSettings}/><ModalActionButton label={prefSaving?text.saving:text.save} disabled={prefSaving||!displayDirty} onclick={saveSettings}/>{/snippet}
</DetailModal>{/if}
